insert into public.destinations
  (id, city, country, flag, image, timezone, best_season, avg_daily_cost_usd, lat, lng, description, has_warning, warning_key, popular_tags)
values
  ('tokyo-japan', 'Tokyo', 'Japan', '🇯🇵', 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1200&q=80', 'Asia/Tokyo (GMT+9)', 'Spring (Cherry Blossoms) & Autumn', 140, 35.6762, 139.6503, 'A mesmerizing fusion of futuristic skyscrapers, serene ancient temples, neon nightlife, and world-class culinary art.', false, null, '["City","Food","Anime","Shopping","Museum","Architecture"]'::jsonb),
  ('kyoto-japan', 'Kyoto', 'Japan', '🇯🇵', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1200&q=80', 'Asia/Tokyo (GMT+9)', 'Autumn (Foliage) & Spring', 120, 35.0116, 135.7681, 'Japan’s cultural heart filled with thousands of classical Buddhist temples, gardens, imperial palaces, Shinto shrines, and traditional wooden houses.', false, null, '["History","Photography","Nature","Romantic","Hidden Gems"]'::jsonb),
  ('paris-france', 'Paris', 'France', '🇫🇷', 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=1200&q=80', 'Europe/Paris (GMT+2)', 'Spring & Autumn', 180, 48.8566, 2.3522, 'The City of Light, famed for iconic monuments, legendary art galleries, cozy sidewalk cafes, haute cuisine, and timeless romance.', false, null, '["Museum","Romantic","Architecture","Food","Cafe","Shopping","Luxury"]'::jsonb),
  ('reykjavik-iceland', 'Reykjavik & Golden Circle', 'Iceland', '🇮🇸', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=1200&q=80', 'Atlantic/Reykjavik (GMT+0)', 'Summer (Midnight Sun) & Winter (Northern Lights)', 210, 64.1466, -21.9426, 'A land of volcanic wonders, thermal lagoons, roaring waterfalls, dramatic fjords, and ethereal Northern Lights displays.', false, null, '["Nature","Mountain","Adventure","Photography","Road Trip","Camping"]'::jsonb),
  ('sydney-australia', 'Sydney', 'Australia', '🇦🇺', 'https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=1200&q=80', 'Australia/Sydney (GMT+10)', 'Spring & Summer (Sept - Feb)', 165, -33.8688, 151.2093, 'Dynamic harbor city famous for the Opera House, sun-kissed beaches, coastal walks, and vibrant coffee culture.', true, 'australia', '["Beach","City","Nature","Cafe","Photography","Adventure"]'::jsonb),
  ('zurich-switzerland', 'Zurich & Interlaken', 'Switzerland', '🇨🇭', 'https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=1200&q=80', 'Europe/Zurich (GMT+2)', 'Summer (Hiking) & Winter (Skiing)', 280, 47.3769, 8.5417, 'Breathtaking Alpine panoramas, crystal-clear mountain lakes, luxury watchmaking, gourmet chocolate, and scenic mountain trains.', true, 'switzerland', '["Mountain","Nature","Luxury","Hiking","Photography","Romantic"]'::jsonb),
  ('rome-italy', 'Rome', 'Italy', '🇮🇹', 'https://images.unsplash.com/photo-1552832230-c0197dd311b5?auto=format&fit=crop&w=1200&q=80', 'Europe/Rome (GMT+2)', 'Spring & Autumn', 150, 41.9028, 12.4964, 'An open-air living museum packed with ancient Roman ruins, Renaissance masterpieces, bustling piazzas, and mouthwatering pasta.', false, null, '["History","Food","Architecture","Museum","Romantic"]'::jsonb),
  ('pyongyang-nk', 'Pyongyang', 'North Korea', '🇰🇵', 'https://images.unsplash.com/photo-1541872703-74c5e44368f9?auto=format&fit=crop&w=1200&q=80', 'Asia/Pyongyang (GMT+9)', 'Autumn', 250, 39.0392, 125.7625, 'A tightly controlled capital city featuring monumental socialist classicism architecture and guided state tours.', true, 'north_korea', '["History","Hidden Gems","Architecture"]'::jsonb),
  ('antarctica-base', 'McMurdo & Peninsula', 'Antarctica', '🇦🇶', 'https://images.unsplash.com/photo-1517411032315-54ef2cb783bb?auto=format&fit=crop&w=1200&q=80', 'Antarctica/McMurdo (GMT+12)', 'Austral Summer (Nov - Mar)', 850, -77.846, 166.676, 'The ultimate white wilderness on Earth. Towering blue icebergs, polar wildlife expeditions, and pristine silence.', true, 'antarctica', '["Adventure","Nature","Photography","Camping"]'::jsonb),
  ('mars-olympus', 'Olympus Mons Sector', 'Mars', '🚀', 'https://images.unsplash.com/photo-1614728894747-a83421e2b9c9?auto=format&fit=crop&w=1200&q=80', 'Mars/UTC-Sol', 'Dust Storm Free Sol Season', 50000, 18.65, -133.8, 'Home to the largest volcano in the Solar System. Red dust, low gravity, sub-zero air, and spectacular extraterrestrial sunsets.', true, 'mars', '["Adventure","Mountain","Photography","Hidden Gems"]'::jsonb)
insert into public.travel_plans
  (title, destination, country, flag_emoji, cover_image, summary, duration_days, season, preferences, companion_style, estimated_cost_usd, transportation, weather_forecast, packing_list, days, comments, creator_id, creator_name, creator_avatar, is_published, likes_count, bookmarks_count, views_count, rating, ratings_count)
values
  ('7 Days in Tokyo: Neon Lights, Temples & Culinary Delights', 'Tokyo', 'Japan', '🇯🇵', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=1200&q=80', 'Experience Tokyo’s duality—from the tranquil Meiji Shrine and Senso-ji Temple to the vibrant electronic districts of Akihabara and Michelin-starred ramen joints.', 7, 'Spring', '["City","Food","Anime","Shopping","History"]'::jsonb, 'Friends', 1450, 'Pasmo/Suica Card + JR Yamanote Subway Line', 'Mild Spring 18°C (64°F), clear skies with cherry blossoms in bloom', '[{"id":"p1","category":"Essentials","item":"Passport & Japan Rail Pass voucher","packed":true},{"id":"p2","category":"Electronics","item":"Portable Power Bank (10,000mAh)","packed":true},{"id":"p3","category":"Clothing","item":"Comfortable Walking Shoes (15k steps/day)","packed":true},{"id":"p4","category":"Documents","item":"Suica/Pasmo Card on Apple Wallet","packed":false},{"id":"p5","category":"Toiletries","item":"Compact Folding Umbrella","packed":false}]'::jsonb, '[{"dayNumber":1,"title":"Arrival & Shibuya Crossing Spectacle","activities":[{"id":"act_1_1","title":"Hotel Check-in & Rest in Shinjuku","category":"Hotel","location":"Shinjuku, Tokyo","description":"Settle into your hotel, get fresh, and pick up your pocket Wi-Fi router.","estimatedDuration":"1.5 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":35.6938,"lng":139.7034,"googleMapsUrl":"https://maps.google.com/?q=Shinjuku+Tokyo"},{"id":"act_1_2","title":"Meiji Jingu Shrine & Harajuku Takeshita Street","category":"History","location":"Shibuya City, Tokyo","description":"Stroll through serene forest paths to the majestic Shinto shrine, then walk down vibrant Takeshita Street for quirky street food.","estimatedDuration":"3 hrs","estimatedCost":15,"timeOfDay":"Afternoon","lat":35.6764,"lng":139.6993,"googleMapsUrl":"https://maps.google.com/?q=Meiji+Jingu"},{"id":"act_1_3","title":"Shibuya Scramble Crossing & Shibuya Sky Sunset","category":"City","location":"Shibuya, Tokyo","description":"Cross the busiest intersection on earth and head up to Shibuya Sky open-air observation deck for a panoramic 360° night view.","estimatedDuration":"2.5 hrs","estimatedCost":20,"timeOfDay":"Evening","lat":35.6595,"lng":139.7004,"googleMapsUrl":"https://maps.google.com/?q=Shibuya+Sky"}]},{"dayNumber":2,"title":"Historic Asakusa & Futuristic Odaiba","activities":[{"id":"act_2_1","title":"Senso-ji Temple & Nakamise Shopping Street","category":"Museum","location":"Asakusa, Tokyo","description":"Explore Tokyo’s oldest Buddhist temple, smell the incense, and try traditional matcha snacks.","estimatedDuration":"2.5 hrs","estimatedCost":10,"timeOfDay":"Morning","lat":35.7148,"lng":139.7967,"googleMapsUrl":"https://maps.google.com/?q=Sensoji+Temple"},{"id":"act_2_2","title":"Tokyo Skytree Observation & Lunch","category":"City","location":"Sumida, Tokyo","description":"Ascend Japan’s tallest structure and enjoy a delicious tonkatsu lunch at Solamachi Mall.","estimatedDuration":"2 hrs","estimatedCost":35,"timeOfDay":"Afternoon","lat":35.7101,"lng":139.8107,"googleMapsUrl":"https://maps.google.com/?q=Tokyo+Skytree"},{"id":"act_2_3","title":"TeamLab Planets Digital Art Museum","category":"Museum","location":"Toyosu, Tokyo","description":"Walk through water and immersive light projection rooms in this iconic world-class digital art sanctuary.","estimatedDuration":"2 hrs","estimatedCost":32,"timeOfDay":"Evening","lat":35.6491,"lng":139.7898,"googleMapsUrl":"https://maps.google.com/?q=TeamLab+Planets"}]}]'::jsonb, '[{"id":"c1","userId":"user_maya","userName":"Maya Lin","userAvatar":"https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=200&q=80","content":"Followed this itinerary last week! The ramen recommendation in Shinjuku was mind-blowing.","rating":5,"createdAt":"3 days ago"},{"id":"c2","userId":"user_david","userName":"David Miller","userAvatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80","content":"Pro tip: book the TeamLab Planets tickets at least 3 weeks in advance. Awesome guide!","rating":5,"createdAt":"5 days ago"}]'::jsonb, null, 'Kenji Takahashi', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80', true, 342, 189, 4200, 4.9, 58),
  ('5 Days in Paris: Art, Gastronomy & Seine River Romance', 'Paris', 'France', '🇫🇷', 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=1200&q=80', 'Soak in the timeless elegance of Paris with Louvre museum passes, Montmartre artists plazas, freshly baked croissants, and an evening sunset cruise along the Seine.', 5, 'Spring', '["Museum","Romantic","Architecture","Food","Cafe"]'::jsonb, 'Couple', 1650, 'Paris Metro Day Pass & Walking', 'Mild & Sunny 16°C (61°F) with light breeze', '[{"id":"pp1","category":"Clothing","item":"Stylish Trench Coat & Scarf","packed":true},{"id":"pp2","category":"Essentials","item":"Museum Pass 4-day ticket","packed":true},{"id":"pp3","category":"Clothing","item":"Comfortable Leather Walking Shoes","packed":false}]'::jsonb, '[{"dayNumber":1,"title":"Monuments of Light & Eiffel Tower Sparkle","activities":[{"id":"pact_1","title":"Louvre Museum Masterpieces Tour","category":"Museum","location":"1st Arrondissement, Paris","description":"Marvel at the Mona Lisa, Venus de Milo, and Winged Victory of Samothrace in the world’s largest art museum.","estimatedDuration":"3 hrs","estimatedCost":22,"timeOfDay":"Morning","lat":48.8606,"lng":2.3376,"googleMapsUrl":"https://maps.google.com/?q=Louvre+Museum"},{"id":"pact_2","title":"Tuileries Garden Picnic & Cafe de Flore Lunch","category":"Cafe","location":"Saint-Germain-des-Prés, Paris","description":"Enjoy fresh baguette, brie cheese, and macaroons in Tuileries before sipping coffee at classic Parisian cafes.","estimatedDuration":"2.5 hrs","estimatedCost":35,"timeOfDay":"Afternoon","lat":48.8634,"lng":2.3275,"googleMapsUrl":"https://maps.google.com/?q=Tuileries+Garden"},{"id":"pact_3","title":"Trocadéro View & Eiffel Tower Light Show","category":"Romantic","location":"7th Arrondissement, Paris","description":"Watch the Eiffel Tower light up in sparkling diamonds at the turn of every hour.","estimatedDuration":"2 hrs","estimatedCost":30,"timeOfDay":"Evening","lat":48.8584,"lng":2.2945,"googleMapsUrl":"https://maps.google.com/?q=Eiffel+Tower"}]}]'::jsonb, '[{"id":"cp1","userId":"user_alex","userName":"Alex Rivers","userAvatar":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80","content":"The sunset spot near Sacré-Cœur was unforgettable! Thanks Sophie.","rating":5,"createdAt":"4 days ago"}]'::jsonb, null, 'Sophie Laurent', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=200&q=80', true, 512, 310, 6800, 4.95, 84),
  ('7 Days Iceland Ring Road: Waterfalls, Glaciers & Northern Lights', 'Reykjavik & Golden Circle', 'Iceland', '🇮🇸', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=1200&q=80', 'Embark on an epic road trip past dramatic geysers, black sand beaches, iceberg lagoons, thermal springs, and volcanic craters.', 7, 'Autumn', '["Nature","Mountain","Adventure","Road Trip","Photography"]'::jsonb, 'Solo', 1890, '4x4 Camper Van / Car Rental', 'Crisp Autumn 6°C (43°F), occasional rain & clear night skies for Aurora', '[{"id":"ip1","category":"Clothing","item":"Thermal Base Layers & Waterproof Jacket","packed":true},{"id":"ip2","category":"Electronics","item":"Camera Tripod for Northern Lights long exposure","packed":true},{"id":"ip3","category":"Toiletries","item":"Quick-dry towel for thermal hot springs","packed":true}]'::jsonb, '[{"dayNumber":1,"title":"Golden Circle Exploration & Blue Lagoon Soak","activities":[{"id":"iact_1","title":"Thingvellir National Park Tectonic Rift","category":"Nature","location":"Golden Circle, Iceland","description":"Walk between the North American and Eurasian tectonic plates in a UNESCO World Heritage valley.","estimatedDuration":"2.5 hrs","estimatedCost":10,"timeOfDay":"Morning","lat":64.2559,"lng":-21.1299,"googleMapsUrl":"https://maps.google.com/?q=Thingvellir+National+Park"},{"id":"iact_2","title":"Gullfoss Waterfall & Strokkur Geysir","category":"Adventure","location":"Haukadalur, Iceland","description":"Witness boiling water erupting 30 meters into the sky every 8 minutes at Geysir, followed by roaring Gullfoss cascades.","estimatedDuration":"2.5 hrs","estimatedCost":0,"timeOfDay":"Afternoon","lat":64.3271,"lng":-20.1199,"googleMapsUrl":"https://maps.google.com/?q=Gullfoss"},{"id":"iact_3","title":"Geothermal Bathing at Blue Lagoon","category":"Nature","location":"Grindavik, Iceland","description":"Relax in mineral-rich milky blue waters surrounded by black lava fields.","estimatedDuration":"3 hrs","estimatedCost":85,"timeOfDay":"Evening","lat":63.8804,"lng":-22.4495,"googleMapsUrl":"https://maps.google.com/?q=Blue+Lagoon+Iceland"}]}]'::jsonb, '[]'::jsonb, null, 'Erik Lindqvist', 'https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?auto=format&fit=crop&w=200&q=80', true, 620, 410, 8900, 4.98, 112);
